import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 32 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(32)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np
import time


def _score(pts, radii):
    return radii.sum()


def _resolve(pts, radii, iters=200):
    """Push circles apart / into the box to remove overlaps."""
    n = len(radii)
    pts = pts.copy()
    radii = radii.copy()
    for _ in range(iters):
        moved = False
        for i in range(n):
            for j in range(i + 1, n):
                d = pts[j] - pts[i]
                dist = np.hypot(d[0], d[1])
                need = radii[i] + radii[j]
                if dist < need and dist > 1e-12:
                    push = (need - dist) * 0.5
                    u = d / dist
                    pts[i] -= u * push
                    pts[j] += u * push
                    moved = True
                elif dist <= 1e-12:
                    pts[j] += np.random.randn(2) * 1e-3
                    moved = True
        for i in range(n):
            r = radii[i]
            for k in range(2):
                if pts[i, k] - r < 0:
                    pts[i, k] = r
                    moved = True
                if pts[i, k] + r > 1:
                    pts[i, k] = 1 - r
                    moved = True
        if not moved:
            break
    return pts


def _grow(pts, radii, budget_deadline):
    """Greedily grow radii, resolving overlaps, until time runs out."""
    n = len(radii)
    best_pts, best_radii = pts.copy(), radii.copy()
    best = _score(pts, radii)
    step = 0.005
    while time.process_time() < budget_deadline:
        # try to grow one circle at a time
        idx = np.random.randint(n)
        trial = radii.copy()
        trial[idx] += step * np.random.rand()
        p = _resolve(pts, trial, iters=60)
        s = _score(p, trial)
        # check validity
        valid = True
        for i in range(n):
            if p[i, 0] - trial[i] < -1e-12 or p[i, 0] + trial[i] > 1 + 1e-12:
                valid = False
                break
            if p[i, 1] - trial[i] < -1e-12 or p[i, 1] + trial[i] > 1 + 1e-12:
                valid = False
                break
        if valid:
            for i in range(n):
                for j in range(i + 1, n):
                    if np.hypot(*(p[j] - p[i])) < trial[i] + trial[j] - 1e-12:
                        valid = False
                        break
                if not valid:
                    break
        if valid and s > best:
            pts, radii = p, trial
            best = s
            best_pts, best_radii = p.copy(), trial.copy()
        else:
            # occasionally try global uniform growth
            trial = radii + step * 0.5
            p = _resolve(pts, trial, iters=80)
            s = _score(p, trial)
            valid = np.all(p - trial[:, None] >= -1e-12) and np.all(p + trial[:, None] <= 1 + 1e-12)
            if valid:
                for i in range(n):
                    for j in range(i + 1, n):
                        if np.hypot(*(p[j] - p[i])) < trial[i] + trial[j] - 1e-12:
                            valid = False
                            break
                    if not valid:
                        break
            if valid and s > best:
                pts, radii = p, trial
                best = s
                best_pts, best_radii = p.copy(), trial.copy()
    return best_pts, best_radii, best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.5

    rng = np.random.default_rng(12345)
    n = 32

    best_pts = None
    best_radii = None
    best_score = -1.0

    # Candidate initial layouts
    candidates = []
    if start is not None:
        s = np.asarray(start, dtype=float)
        candidates.append((s[:, :2].copy(), s[:, 2].copy()))

    # hexagonal-ish packing
    for k in range(6, 9):
        pts = []
        for j in range(k):
            for i in range(k):
                x = (i + 0.5 + 0.5 * (j % 2)) / k
                y = (j + 0.5) / k
                if 0 <= x <= 1:
                    pts.append((x, y))
        pts = pts[:n]
        while len(pts) < n:
            pts.append((rng.random(), rng.random()))
        P = np.array(pts[:n])
        R = np.full(n, 0.03)
        candidates.append((P, R))

    # random jittered grid
    k = 6
    P = np.array([((i + 0.5 + rng.normal(0, 0.05)) / k,
                   (j + 0.5 + rng.normal(0, 0.05)) / k)
                  for j in range(k) for i in range(k)])[:n]
    while len(P) < n:
        P = np.vstack([P, [rng.random(), rng.random()]])
    candidates.append((P, np.full(n, 0.03)))

    for P, R in candidates:
        P = _resolve(P, R, iters=100)
        p, r, s = _grow(P, R, deadline)
        if s > best_score:
            best_score = s
            best_pts, best_radii = p, r
        if time.process_time() > deadline:
            break

    # Final safety shrink
    best_radii = best_radii * (1 - 1e-9)
    # Ensure feasibility strictly
    for _ in range(200):
        ok = True
        for i in range(n):
            if best_pts[i, 0] - best_radii[i] < 0 or best_pts[i, 0] + best_radii[i] > 1:
                best_radii[i] *= 0.999
                ok = False
            if best_pts[i, 1] - best_radii[i] < 0 or best_pts[i, 1] + best_radii[i] > 1:
                best_radii[i] *= 0.999
                ok = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(*(best_pts[j] - best_pts[i]))
                if d < best_radii[i] + best_radii[j]:
                    best_radii[i] *= 0.999
                    best_radii[j] *= 0.999
                    ok = False
        if ok:
            break

    out = np.column_stack([best_pts, best_radii])
    return out

import numpy as np
import time
from scipy.optimize import minimize


def construct(budget_seconds, start):
    t0 = time.process_time()

    if start is not None:
        arr = np.asarray(start, dtype=float).copy()
    else:
        k = int(np.ceil(np.sqrt(32)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
        arr = np.array([[x, y, 0.02] for x, y in pts])

    n = arr.shape[0]
    x0 = arr.reshape(-1).copy()

    # Bounds: x,y in [0,1], r in [0,0.5]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 0.5))

    def unpack(z):
        return z.reshape(n, 3)

    def objective(z):
        return -np.sum(z[2::3])

    def obj_grad(z):
        g = np.zeros_like(z)
        g[2::3] = -1.0
        return g

    # Build constraint list
    cons = []

    # Wall constraints per circle: x-r>=0, 1-x-r>=0, y-r>=0, 1-y-r>=0
    for i in range(n):
        def make_wall(i, kind):
            def f(z):
                p = unpack(z)
                x, y, r = p[i]
                if kind == 0:
                    return x - r
                elif kind == 1:
                    return 1.0 - x - r
                elif kind == 2:
                    return y - r
                else:
                    return 1.0 - y - r
            return f
        for kind in range(4):
            cons.append({'type': 'ineq', 'fun': make_wall(i, kind)})

    # Pair constraints
    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(z):
                    p = unpack(z)
                    xi, yi, ri = p[i]
                    xj, yj, rj = p[j]
                    dx = xi - xj
                    dy = yi - yj
                    return dx * dx + dy * dy - (ri + rj) ** 2
                return f
            cons.append({'type': 'ineq', 'fun': make_pair(i, j)})

    # Time-aware callback to stop early
    class TimeUp(Exception):
        pass

    deadline = t0 + budget_seconds - 0.5

    def callback(z):
        if time.process_time() > deadline:
            raise TimeUp()

    try:
        res = minimize(
            objective, x0, jac=obj_grad, method='SLSQP',
            bounds=bounds, constraints=cons,
            options={'maxiter': 2000, 'ftol': 1e-12},
            callback=callback,
        )
        z = res.x
    except TimeUp:
        z = x0

    p = unpack(z).copy()

    # Shrink radii for safety and clamp centres
    p[:, 2] = np.maximum(p[:, 2] - 1e-9, 1e-12)
    for i in range(n):
        r = p[i, 2]
        p[i, 0] = min(max(p[i, 0], r), 1.0 - r)
        p[i, 1] = min(max(p[i, 1], r), 1.0 - r)

    return p

import numpy as np
import time
from scipy.optimize import minimize


def _polish(arr, deadline, maxiter=2000):
    """Analytic-gradient SLSQP polish of a (n,3) array. Returns best feasible array."""
    n = arr.shape[0]
    x0 = arr.reshape(-1).copy()

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 0.5))

    def unpack(z):
        return z.reshape(n, 3)

    def objective(z):
        return -np.sum(z[2::3])

    def obj_grad(z):
        g = np.zeros_like(z)
        g[2::3] = -1.0
        return g

    cons = []
    for i in range(n):
        def make_wall(i, kind):
            def f(z):
                p = unpack(z)
                x, y, r = p[i]
                if kind == 0:
                    return x - r
                elif kind == 1:
                    return 1.0 - x - r
                elif kind == 2:
                    return y - r
                else:
                    return 1.0 - y - r
            return f
        for kind in range(4):
            cons.append({'type': 'ineq', 'fun': make_wall(i, kind)})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(z):
                    p = unpack(z)
                    xi, yi, ri = p[i]
                    xj, yj, rj = p[j]
                    dx = xi - xj
                    dy = yi - yj
                    return dx * dx + dy * dy - (ri + rj) ** 2
                return f
            cons.append({'type': 'ineq', 'fun': make_pair(i, j)})

    class TimeUp(Exception):
        pass

    def callback(z):
        if time.process_time() > deadline:
            raise TimeUp()

    try:
        res = minimize(
            objective, x0, jac=obj_grad, method='SLSQP',
            bounds=bounds, constraints=cons,
            options={'maxiter': maxiter, 'ftol': 1e-12},
            callback=callback,
        )
        z = res.x
    except TimeUp:
        z = x0

    return unpack(z).copy()


def _feasible(p):
    """Check feasibility with zero tolerance (after internal shrink)."""
    n = p.shape[0]
    for i in range(n):
        x, y, r = p[i]
        if r <= 0:
            return False
        if x - r < 0 or x + r > 1 or y - r < 0 or y + r > 1:
            return False
    for i in range(n):
        for j in range(i + 1, n):
            dx = p[i, 0] - p[j, 0]
            dy = p[i, 1] - p[j, 1]
            if dx * dx + dy * dy < (p[i, 2] + p[j, 2]) ** 2:
                return False
    return True


def _project(p):
    """Clamp centres and shrink radii to fit square."""
    n = p.shape[0]
    for i in range(n):
        r = p[i, 2]
        if r <= 0:
            r = 1e-6
        if r > 0.5:
            r = 0.5
        p[i, 2] = r
        p[i, 0] = min(max(p[i, 0], r), 1.0 - r)
        p[i, 1] = min(max(p[i, 1], r), 1.0 - r)
    return p


def construct(budget_seconds, start):
    t0 = time.process_time()

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
    else:
        k = int(np.ceil(np.sqrt(32)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
        base = np.array([[x, y, 0.02] for x, y in pts])

    n = base.shape[0]

    # First polish the start itself to ensure a good baseline
    deadline = t0 + budget_seconds - 0.6
    best = _polish(base.copy(), min(deadline, time.process_time() + 1.0))
    best = _project(best.copy())
    best_score = np.sum(best[:, 2])

    rng = np.random.default_rng(12345)

    n_restarts = 8
    for k in range(n_restarts):
        now = time.process_time()
        remaining = deadline - now
        if remaining <= 0.2:
            break
        # per-restart time budget
        per = min(1.0, remaining / max(1, (n_restarts - k)))

        cand = base.copy()
        cand[:, 2] *= 0.95
        cand[:, 0] += rng.uniform(-0.008, 0.008, n)
        cand[:, 1] += rng.uniform(-0.008, 0.008, n)
        cand[:, 2] += rng.uniform(-0.004, 0.004, n)
        cand = _project(cand)

        res = _polish(cand, time.process_time() + per)
        res = _project(res)
        score = np.sum(res[:, 2])
        if score > best_score:
            best_score = score
            best = res

    # final safety shrink
    out = best.copy()
    out[:, 2] = np.maximum(out[:, 2] - 1e-10, 1e-12)
    out = _project(out)
    # ensure strict feasibility; shrink more if needed
    for _ in range(5):
        if _feasible(out):
            break
        out[:, 2] = np.maximum(out[:, 2] - 1e-9, 1e-12)
        out = _project(out)

    return out

import numpy as np
import time
from scipy.optimize import minimize, linprog, root


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.7
    n = 32

    def margin(p):
        x, y, r = p[:, 0], p[:, 1], p[:, 2]
        m = min((x - r).min(), (1 - x - r).min(),
                (y - r).min(), (1 - y - r).min())
        for i in range(n):
            dx = x[i] - x[i + 1:]
            dy = y[i] - y[i + 1:]
            d = np.sqrt(dx * dx + dy * dy) - r[i] - r[i + 1:]
            if d.size:
                m = min(m, d.min())
        return m

    if start is not None:
        p = np.asarray(start, dtype=float).copy()
        if p.shape != (n, 3):
            p = None
    else:
        p = None
    if p is None:
        k = int(np.ceil(np.sqrt(n)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        p = np.array([[x, y, 0.02] for x, y in pts])

    p[:, 2] = np.maximum(p[:, 2] - 1e-7, 1e-6)
    p[:, 0] = np.clip(p[:, 0], p[:, 2], 1 - p[:, 2])
    p[:, 1] = np.clip(p[:, 1], p[:, 2], 1 - p[:, 2])

    def unpack(z):
        return z.reshape(n, 3)

    def objective(z):
        return -np.sum(z[2::3])

    def obj_grad(z):
        g = np.zeros_like(z)
        g[2::3] = -1.0
        return g

    bounds = []
    for _ in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 0.5))

    idx_i, idx_j = np.triu_indices(n, k=1)
    n_pairs = len(idx_i)

    def wall_con(z):
        q = unpack(z)
        x, y, r = q[:, 0], q[:, 1], q[:, 2]
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * n, 3 * n))
        for i in range(n):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[n + i, 3 * i] = -1.0; J[n + i, 3 * i + 2] = -1.0
            J[2 * n + i, 3 * i + 1] = 1.0; J[2 * n + i, 3 * i + 2] = -1.0
            J[3 * n + i, 3 * i + 1] = -1.0; J[3 * n + i, 3 * i + 2] = -1.0
        return J

    def pair_con(z):
        q = unpack(z)
        xi, yi, ri = q[idx_i, 0], q[idx_i, 1], q[idx_i, 2]
        xj, yj, rj = q[idx_j, 0], q[idx_j, 1], q[idx_j, 2]
        dx = xi - xj; dy = yi - yj
        return dx * dx + dy * dy - (ri + rj) ** 2

    def pair_jac(z):
        q = unpack(z)
        xi, yi, ri = q[idx_i, 0], q[idx_i, 1], q[idx_i, 2]
        xj, yj, rj = q[idx_j, 0], q[idx_j, 1], q[idx_j, 2]
        dx = xi - xj; dy = yi - yj
        J = np.zeros((n_pairs, 3 * n))
        rows = np.arange(n_pairs)
        J[rows, 3 * idx_i] = 2 * dx
        J[rows, 3 * idx_i + 1] = 2 * dy
        J[rows, 3 * idx_i + 2] = -2 * (ri + rj)
        J[rows, 3 * idx_j] = -2 * dx
        J[rows, 3 * idx_j + 1] = -2 * dy
        J[rows, 3 * idx_j + 2] = -2 * (ri + rj)
        return J

    cons = [
        {'type': 'ineq', 'fun': wall_con, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair_con, 'jac': pair_jac},
    ]

    best = p.copy()
    best_score = p[:, 2].sum() if margin(p) >= -1e-9 else -1e9

    def lp_radii(centers):
        x = centers[:, 0]; y = centers[:, 1]
        wall_cap = np.minimum(np.minimum(x, 1 - x), np.minimum(y, 1 - y))
        wall_cap = np.maximum(wall_cap, 0.0)
        c = -np.ones(n)
        dx = x[idx_i] - x[idx_j]
        dy = y[idx_i] - y[idx_j]
        d = np.hypot(dx, dy)
        A_pair = np.zeros((n_pairs, n))
        A_pair[np.arange(n_pairs), idx_i] = 1.0
        A_pair[np.arange(n_pairs), idx_j] = 1.0
        bounds_lp = [(0.0, wall_cap[i]) for i in range(n)]
        try:
            res = linprog(c, A_ub=A_pair, b_ub=d, bounds=bounds_lp,
                          method='highs')
            if res.success:
                return np.maximum(res.x, 0.0)
        except Exception:
            pass
        rr = wall_cap.copy()
        for i in range(n):
            for j in range(i + 1, n):
                dij = np.hypot(x[i] - x[j], y[i] - y[j])
                if rr[i] + rr[j] > dij:
                    s = (rr[i] + rr[j] - dij) / 2.0
                    rr[i] = max(rr[i] - s, 0.0)
                    rr[j] = max(rr[j] - s, 0.0)
        return rr

    def compress(pin, deadline_local):
        q = pin.copy()
        q[:, 2] = np.maximum(q[:, 2] * 0.85, 1e-6)
        fails = 0
        for outer in range(200):
            if time.process_time() > deadline_local:
                break
            q[:, 2] *= 1.002
            ok = True
            for _ in range(40):
                moved = False
                for i in range(n):
                    for j in range(i + 1, n):
                        dx = q[i, 0] - q[j, 0]
                        dy = q[i, 1] - q[j, 1]
                        d = np.hypot(dx, dy)
                        s = q[i, 2] + q[j, 2]
                        if d < s:
                            moved = True
                            if d < 1e-12:
                                ang = np.random.uniform(0, 2 * np.pi)
                                ux, uy = np.cos(ang), np.sin(ang)
                            else:
                                ux, uy = dx / d, dy / d
                            ov = (s - d) / 2.0
                            q[i, 0] += ux * ov
                            q[i, 1] += uy * ov
                            q[j, 0] -= ux * ov
                            q[j, 1] -= uy * ov
                for i in range(n):
                    r = q[i, 2]
                    if q[i, 0] < r:
                        q[i, 0] = r
                        moved = True
                    elif q[i, 0] > 1 - r:
                        q[i, 0] = 1 - r
                        moved = True
                    if q[i, 1] < r:
                        q[i, 1] = r
                        moved = True
                    elif q[i, 1] > 1 - r:
                        q[i, 1] = 1 - r
                        moved = True
                if not moved:
                    break
            overlapped = False
            for i in range(n):
                for j in range(i + 1, n):
                    dx = q[i, 0] - q[j, 0]
                    dy = q[i, 1] - q[j, 1]
                    d = np.hypot(dx, dy)
                    if d < q[i, 2] + q[j, 2] - 1e-9:
                        overlapped = True
                        break
                if overlapped:
                    break
            if overlapped:
                q[:, 2] /= 1.002
                fails += 1
                if fails >= 5:
                    break
            else:
                fails = 0
        q[:, 2] = lp_radii(q[:, :2])
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
        return q

    def full_slsqp(z0, deadline_local):
        class TimeUp(Exception):
            pass

        def cb(_z):
            if time.process_time() > deadline_local:
                raise TimeUp()

        try:
            res = minimize(objective, z0, jac=obj_grad, method='SLSQP',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': 1000, 'ftol': 1e-14},
                           callback=cb)
            return res.x
        except TimeUp:
            return None
        except Exception:
            return None

    def clean(q):
        q = q.copy()
        q[:, 2] = np.maximum(q[:, 2], 1e-12)
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
        for i in range(n):
            for j in range(i + 1, n):
                dx = q[i, 0] - q[j, 0]; dy = q[i, 1] - q[j, 1]
                d = np.hypot(dx, dy)
                s = q[i, 2] + q[j, 2]
                if d < s and s > 0:
                    shrink = (s - d) / 2.0 + 1e-12
                    q[i, 2] = max(q[i, 2] - shrink, 1e-12)
                    q[j, 2] = max(q[j, 2] - shrink, 1e-12)
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
        return q

    # Try compression on best
    try:
        qc = compress(best, deadline)
        z0 = qc.reshape(-1).copy()
        z = full_slsqp(z0, deadline)
        if z is not None:
            q = clean(unpack(z))
            sc = q[:, 2].sum()
            if sc > best_score and margin(q) >= -1e-9:
                best = q
                best_score = sc
    except Exception:
        pass

    # ---- Exact-polish phase on active contact set ----
    try:
        if time.process_time() < deadline - 0.3:
            q = best.copy()
            x, y, r = q[:, 0], q[:, 1], q[:, 2]
            dx = x[idx_i] - x[idx_j]
            dy = y[idx_i] - y[idx_j]
            d = np.hypot(dx, dy)
            pair_gaps = d - (r[idx_i] + r[idx_j])
            active_pairs = np.where(pair_gaps < 1e-5)[0]
            wg = np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])
            active_walls = np.where(wg < 1e-5)[0]

            if len(active_pairs) > 0 or len(active_walls) > 0:
                qp = q.copy()
                qp[:, 2] = np.maximum(qp[:, 2] - 1e-6, 1e-9)
                qp[:, 0] = np.clip(qp[:, 0], qp[:, 2], 1 - qp[:, 2])
                qp[:, 1] = np.clip(qp[:, 1], qp[:, 2], 1 - qp[:, 2])

                ap = active_pairs
                aw = active_walls

                def pair_con_sub(z):
                    return pair_con(z)[ap]

                def pair_jac_sub(z):
                    return pair_jac(z)[ap]

                def wall_con_sub(z):
                    return wall_con(z)[aw]

                def wall_jac_sub(z):
                    return wall_jac(z)[aw]

                eq_cons = []
                if len(ap) > 0:
                    eq_cons.append({'type': 'eq', 'fun': pair_con_sub,
                                    'jac': pair_jac_sub})
                if len(aw) > 0:
                    eq_cons.append({'type': 'eq', 'fun': wall_con_sub,
                                    'jac': wall_jac_sub})

                class TimeUp(Exception):
                    pass

                def cb2(_z):
                    if time.process_time() > deadline - 0.2:
                        raise TimeUp()

                try:
                    res = minimize(objective, qp.reshape(-1).copy(),
                                   jac=obj_grad, method='SLSQP',
                                   bounds=bounds, constraints=eq_cons,
                                   options={'maxiter': 400, 'ftol': 1e-16},
                                   callback=cb2)
                    q2 = unpack(res.x).copy()
                    q2[:, 2] = lp_radii(q2[:, :2])
                    q2[:, 0] = np.clip(q2[:, 0], q2[:, 2], 1 - q2[:, 2])
                    q2[:, 1] = np.clip(q2[:, 1], q2[:, 2], 1 - q2[:, 2])
                    z2 = full_slsqp(q2.reshape(-1).copy(), deadline - 0.1)
                    if z2 is not None:
                        q2 = clean(unpack(z2))
                    else:
                        q2 = clean(q2)
                    sc2 = q2[:, 2].sum()
                    if sc2 > best_score and margin(q2) >= -1e-12:
                        best = q2
                        best_score = sc2
                except TimeUp:
                    pass
                except Exception:
                    pass
    except Exception:
        pass

    rng = np.random.default_rng(0)
    attempts = 0
    while time.process_time() < deadline and attempts < 60:
        attempts += 1
        if attempts == 1:
            z0 = best.reshape(-1).copy()
        else:
            scale = 0.005 if attempts < 10 else 0.02
            noise = rng.normal(0, scale, size=(n, 2))
            q0 = best.copy()
            q0[:, :2] = np.clip(q0[:, :2] + noise, 0.0, 1.0)
            radii = lp_radii(q0[:, :2])
            q0[:, 2] = np.maximum(radii - 1e-9, 1e-9)
            q0[:, 0] = np.clip(q0[:, 0], q0[:, 2], 1 - q0[:, 2])
            q0[:, 1] = np.clip(q0[:, 1], q0[:, 2], 1 - q0[:, 2])
            z0 = q0.reshape(-1).copy()

        z = full_slsqp(z0, deadline)
        if z is None:
            break
        q = clean(unpack(z))
        sc = q[:, 2].sum()
        if sc > best_score and margin(q) >= -1e-9:
            best = q
            best_score = sc

    # ---- NEW: exact active-contact Newton polish with multipliers ----
    def exact_polish(qin, deadline_local):
        q = qin.copy()
        x, y, r = q[:, 0], q[:, 1], q[:, 2]
        dx = x[idx_i] - x[idx_j]
        dy = y[idx_i] - y[idx_j]
        d = np.hypot(dx, dy)
        pair_gaps = d - (r[idx_i] + r[idx_j])
        tol = 1e-6
        ap = np.where(pair_gaps < tol)[0]
        wg = np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])
        aw = np.where(wg < tol)[0]
        m = len(ap) + len(aw)
        if m == 0:
            return q
        def cons_all(z):
            parts = []
            if len(ap):
                parts.append(pair_con(z)[ap])
            if len(aw):
                parts.append(wall_con(z)[aw])
            return np.concatenate(parts)
        def cons_jac_all(z):
            rows = []
            if len(ap):
                rows.append(pair_jac(z)[ap])
            if len(aw):
                rows.append(wall_jac(z)[aw])
            return np.vstack(rows)
        z = q.reshape(-1).copy()
        J = cons_jac_all(z)
        g = obj_grad(z)
        try:
            lam, *_ = np.linalg.lstsq(J.T, -g, rcond=None)
        except Exception:
            lam = np.zeros(m)
        def F(u):
            zz = u[:3 * n]
            ll = u[3 * n:]
            c = cons_all(zz)
            Jz = cons_jac_all(zz)
            grad = obj_grad(zz) + Jz.T @ ll
            return np.concatenate([c, grad])
        u0 = np.concatenate([z, lam])
        try:
            sol = root(F, u0, method='hybr', options={'xtol': 1e-14, 'maxfev': 2000})
            if not np.all(np.isfinite(sol.x)):
                return q
            zz = sol.x[:3 * n]
            qq = unpack(zz).copy()
        except Exception:
            return q
        qq[:, 2] = lp_radii(qq[:, :2])
        qq[:, 0] = np.clip(qq[:, 0], qq[:, 2], 1 - qq[:, 2])
        qq[:, 1] = np.clip(qq[:, 1], qq[:, 2], 1 - qq[:, 2])
        def feasible(scale):
            ql = qq.astype(np.longdouble).copy()
            ql[:, 2] *= scale
            xx, yy, rr = ql[:, 0], ql[:, 1], ql[:, 2]
            if np.any(xx - rr < 0) or np.any(xx + rr > 1):
                return False
            if np.any(yy - rr < 0) or np.any(yy + rr > 1):
                return False
            for i in range(n):
                ddx = xx[i] - xx[i + 1:]
                ddy = yy[i] - yy[i + 1:]
                dd = np.sqrt(ddx * ddx + ddy * ddy)
                if np.any(dd < rr[i] + rr[i + 1:]):
                    return False
            return True
        lo, hi = 0.0, 1.0
        if feasible(1.0):
            scale = 1.0
        else:
            for _ in range(80):
                mid = 0.5 * (lo + hi)
                if feasible(mid):
                    lo = mid
                else:
                    hi = mid
            scale = lo
        qq[:, 2] *= scale
        for _ in range(200):
            if margin(qq) >= 0.0:
                break
            qq[:, 2] *= (1.0 - 1e-15)
        return qq

    try:
        if time.process_time() < deadline - 0.05:
            qp = exact_polish(best, deadline)
            if qp is not None:
                ok = True
                if np.any(qp[:, 2] <= 0):
                    ok = False
                xx, yy, rr = qp[:, 0], qp[:, 1], qp[:, 2]
                if np.any(xx - rr < 0) or np.any(xx + rr > 1):
                    ok = False
                if np.any(yy - rr < 0) or np.any(yy + rr > 1):
                    ok = False
                if ok:
                    for i in range(n):
                        ddx = xx[i] - xx[i + 1:]
                        ddy = yy[i] - yy[i + 1:]
                        dd = np.sqrt(ddx * ddx + ddy * ddy)
                        if np.any(dd < rr[i] + rr[i + 1:]):
                            ok = False
                            break
                if ok:
                    sc = qp[:, 2].sum()
                    if sc > best_score:
                        best = qp
                        best_score = sc
    except Exception:
        pass

    # ---- NEW EXPERIMENT: Newton on active contact equalities + equality SLSQP ----
    try:
        if time.process_time() < deadline - 0.15:
            q = best.copy()
            x, y, r = q[:, 0], q[:, 1], q[:, 2]
            dx = x[idx_i] - x[idx_j]
            dy = y[idx_i] - y[idx_j]
            d = np.hypot(dx, dy)
            pair_gaps = d - (r[idx_i] + r[idx_j])
            ap = np.where(pair_gaps < 1e-7)[0]
            wg = np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])
            aw = np.where(wg < 1e-7)[0]

            if len(ap) > 0 or len(aw) > 0:
                def cons_act(z):
                    parts = []
                    if len(ap):
                        parts.append(pair_con(z)[ap])
                    if len(aw):
                        parts.append(wall_con(z)[aw])
                    return np.concatenate(parts)

                def jac_act(z):
                    rows = []
                    if len(ap):
                        rows.append(pair_jac(z)[ap])
                    if len(aw):
                        rows.append(wall_jac(z)[aw])
                    return np.vstack(rows)

                z = q.reshape(-1).copy()
                for _ in range(20):
                    if time.process_time() > deadline - 0.12:
                        break
                    Fv = cons_act(z)
                    if Fv.size == 0 or np.max(np.abs(Fv)) < 1e-13:
                        break
                    J = jac_act(z)
                    try:
                        dz = np.linalg.lstsq(J, -Fv, rcond=None)[0]
                    except Exception:
                        break
                    if not np.all(np.isfinite(dz)):
                        break
                    z = z + dz

                qn = unpack(z).copy()
                qn[:, 2] = lp_radii(qn[:, :2])
                qn[:, 0] = np.clip(qn[:, 0], qn[:, 2], 1 - qn[:, 2])
                qn[:, 1] = np.clip(qn[:, 1], qn[:, 2], 1 - qn[:, 2])

                # equality-only SLSQP on the same active set
                eq_cons = []
                if len(ap) > 0:
                    eq_cons.append({'type': 'eq',
                                    'fun': lambda zz: pair_con(zz)[ap],
                                    'jac': lambda zz: pair_jac(zz)[ap]})
                if len(aw) > 0:
                    eq_cons.append({'type': 'eq',
                                    'fun': lambda zz: wall_con(zz)[aw],
                                    'jac': lambda zz: wall_jac(zz)[aw]})

                class TimeUp2(Exception):
                    pass

                def cb3(_z):
                    if time.process_time() > deadline - 0.08:
                        raise TimeUp2()

                qn2 = qn
                if eq_cons:
                    try:
                        res = minimize(objective, qn.reshape(-1).copy(),
                                       jac=obj_grad, method='SLSQP',
                                       bounds=bounds, constraints=eq_cons,
                                       options={'maxiter': 300, 'ftol': 1e-16},
                                       callback=cb3)
                        qn2 = unpack(res.x).copy()
                    except TimeUp2:
                        qn2 = qn
                    except Exception:
                        qn2 = qn

                qn2[:, 2] = lp_radii(qn2[:, :2])
                qn2[:, 0] = np.clip(qn2[:, 0], qn2[:, 2], 1 - qn2[:, 2])
                qn2[:, 1] = np.clip(qn2[:, 1], qn2[:, 2], 1 - qn2[:, 2])
                qn2[:, 2] = np.maximum(qn2[:, 2] - 1e-12, 1e-12)
                qn2[:, 0] = np.clip(qn2[:, 0], qn2[:, 2], 1 - qn2[:, 2])
                qn2[:, 1] = np.clip(qn2[:, 1], qn2[:, 2], 1 - qn2[:, 2])

                if margin(qn2) >= 0.0:
                    sc = qn2[:, 2].sum()
                    if sc > best_score:
                        best = qn2
                        best_score = sc
    except Exception:
        pass

    q = best.copy()
    q[:, 2] = np.maximum(q[:, 2] - 1e-15, 1e-12)
    q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
    q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
    for _ in range(500):
        if margin(q) >= 0.0:
            break
        q[:, 2] *= (1.0 - 1e-15)
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
    return q

import numpy as np
import time
from scipy.optimize import linprog, minimize


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6
    n = 32

    idx_i, idx_j = np.triu_indices(n, k=1)
    n_pairs = len(idx_i)

    def margin(p):
        x, y, r = p[:, 0], p[:, 1], p[:, 2]
        m = min((x - r).min(), (1 - x - r).min(),
                (y - r).min(), (1 - y - r).min())
        for i in range(n):
            dx = x[i] - x[i + 1:]
            dy = y[i] - y[i + 1:]
            d = np.sqrt(dx * dx + dy * dy) - r[i] - r[i + 1:]
            if d.size:
                m = min(m, d.min())
        return m

    if start is not None:
        p = np.asarray(start, dtype=float).copy()
        if p.shape != (n, 3):
            p = None
    else:
        p = None
    if p is None:
        k = int(np.ceil(np.sqrt(n)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        p = np.array([[x, y, 0.02] for x, y in pts])

    p[:, 2] = np.maximum(p[:, 2] - 1e-7, 1e-6)
    p[:, 0] = np.clip(p[:, 0], p[:, 2], 1 - p[:, 2])
    p[:, 1] = np.clip(p[:, 1], p[:, 2], 1 - p[:, 2])

    def unpack(z):
        return z.reshape(n, 3)

    def objective(z):
        return -np.sum(z[2::3])

    def obj_grad(z):
        g = np.zeros_like(z)
        g[2::3] = -1.0
        return g

    bounds = []
    for _ in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 0.5))

    def wall_con(z):
        q = unpack(z)
        x, y, r = q[:, 0], q[:, 1], q[:, 2]
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * n, 3 * n))
        for i in range(n):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[n + i, 3 * i] = -1.0; J[n + i, 3 * i + 2] = -1.0
            J[2 * n + i, 3 * i + 1] = 1.0; J[2 * n + i, 3 * i + 2] = -1.0
            J[3 * n + i, 3 * i + 1] = -1.0; J[3 * n + i, 3 * i + 2] = -1.0
        return J

    def pair_con(z):
        q = unpack(z)
        xi, yi, ri = q[idx_i, 0], q[idx_i, 1], q[idx_i, 2]
        xj, yj, rj = q[idx_j, 0], q[idx_j, 1], q[idx_j, 2]
        dx = xi - xj; dy = yi - yj
        return dx * dx + dy * dy - (ri + rj) ** 2

    def pair_jac(z):
        q = unpack(z)
        xi, yi, ri = q[idx_i, 0], q[idx_i, 1], q[idx_i, 2]
        xj, yj, rj = q[idx_j, 0], q[idx_j, 1], q[idx_j, 2]
        dx = xi - xj; dy = yi - yj
        J = np.zeros((n_pairs, 3 * n))
        rows = np.arange(n_pairs)
        J[rows, 3 * idx_i] = 2 * dx
        J[rows, 3 * idx_i + 1] = 2 * dy
        J[rows, 3 * idx_i + 2] = -2 * (ri + rj)
        J[rows, 3 * idx_j] = -2 * dx
        J[rows, 3 * idx_j + 1] = -2 * dy
        J[rows, 3 * idx_j + 2] = -2 * (ri + rj)
        return J

    cons = [
        {'type': 'ineq', 'fun': wall_con, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair_con, 'jac': pair_jac},
    ]

    best = p.copy()
    best_score = p[:, 2].sum() if margin(p) >= -1e-9 else -1e9

    def lp_radii(centers):
        x = centers[:, 0]; y = centers[:, 1]
        wall_cap = np.minimum(np.minimum(x, 1 - x), np.minimum(y, 1 - y))
        wall_cap = np.maximum(wall_cap, 0.0)
        c = -np.ones(n)
        dx = x[idx_i] - x[idx_j]
        dy = y[idx_i] - y[idx_j]
        d = np.hypot(dx, dy)
        A_pair = np.zeros((n_pairs, n))
        A_pair[np.arange(n_pairs), idx_i] = 1.0
        A_pair[np.arange(n_pairs), idx_j] = 1.0
        bounds_lp = [(0.0, wall_cap[i]) for i in range(n)]
        try:
            res = linprog(c, A_ub=A_pair, b_ub=d, bounds=bounds_lp,
                          method='highs')
            if res.success:
                return np.maximum(res.x, 0.0)
        except Exception:
            pass
        rr = wall_cap.copy()
        for i in range(n):
            for j in range(i + 1, n):
                dij = np.hypot(x[i] - x[j], y[i] - y[j])
                if rr[i] + rr[j] > dij:
                    s = (rr[i] + rr[j] - dij) / 2.0
                    rr[i] = max(rr[i] - s, 0.0)
                    rr[j] = max(rr[j] - s, 0.0)
        return rr

    def full_slsqp(z0, deadline_local, maxiter=1000, ftol=1e-14):
        class TimeUp(Exception):
            pass

        def cb(_z):
            if time.process_time() > deadline_local:
                raise TimeUp()

        try:
            res = minimize(objective, z0, jac=obj_grad, method='SLSQP',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': maxiter, 'ftol': ftol},
                           callback=cb)
            return res.x
        except TimeUp:
            return None
        except Exception:
            return None

    def clean(q):
        q = q.copy()
        q[:, 2] = np.maximum(q[:, 2], 1e-12)
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
        for i in range(n):
            for j in range(i + 1, n):
                dx = q[i, 0] - q[j, 0]; dy = q[i, 1] - q[j, 1]
                d = np.hypot(dx, dy)
                s = q[i, 2] + q[j, 2]
                if d < s and s > 0:
                    shrink = (s - d) / 2.0 + 1e-12
                    q[i, 2] = max(q[i, 2] - shrink, 1e-12)
                    q[j, 2] = max(q[j, 2] - shrink, 1e-12)
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
        return q

    # ---- NEW: exact-polish phase on active contact set (Newton with multipliers) ----
    def exact_polish(qin, deadline_local):
        q = qin.copy()
        x, y, r = q[:, 0], q[:, 1], q[:, 2]
        dx = x[idx_i] - x[idx_j]
        dy = y[idx_i] - y[idx_j]
        d = np.hypot(dx, dy)
        pair_gaps = d - (r[idx_i] + r[idx_j])
        tol = 1e-6
        ap = np.where(pair_gaps < tol)[0]
        wg = np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])
        aw = np.where(wg < tol)[0]
        m = len(ap) + len(aw)
        if m == 0:
            return q

        def cons_all(z):
            parts = []
            if len(ap):
                parts.append(pair_con(z)[ap])
            if len(aw):
                parts.append(wall_con(z)[aw])
            return np.concatenate(parts)

        def cons_jac_all(z):
            rows = []
            if len(ap):
                rows.append(pair_jac(z)[ap])
            if len(aw):
                rows.append(wall_jac(z)[aw])
            return np.vstack(rows)

        z = q.reshape(-1).copy()
        J = cons_jac_all(z)
        g = obj_grad(z)
        try:
            lam, *_ = np.linalg.lstsq(J.T, -g, rcond=None)
        except Exception:
            lam = np.zeros(m)

        def F(u):
            zz = u[:3 * n]
            ll = u[3 * n:]
            c = cons_all(zz)
            Jz = cons_jac_all(zz)
            grad = obj_grad(zz) + Jz.T @ ll
            return np.concatenate([c, grad])

        u = np.concatenate([z, lam])
        try:
            for _ in range(50):
                if time.process_time() > deadline_local:
                    break
                Fu = F(u)
                if np.max(np.abs(Fu)) < 1e-14:
                    break
                # finite-difference Jacobian of F (cheap since m+3n modest)
                eps = 1e-8
                dim = u.size
                Jf = np.zeros((Fu.size, dim))
                for k in range(dim):
                    du = np.zeros(dim)
                    du[k] = eps
                    Jf[:, k] = (F(u + du) - Fu) / eps
                try:
                    step = np.linalg.lstsq(Jf, -Fu, rcond=None)[0]
                except Exception:
                    break
                # line search
                alpha = 1.0
                base = np.linalg.norm(Fu)
                for _ls in range(20):
                    un = u + alpha * step
                    fn = np.linalg.norm(F(un))
                    if fn < base:
                        u = un
                        break
                    alpha *= 0.5
                else:
                    break
        except Exception:
            return q

        zz = u[:3 * n]
        qq = unpack(zz).copy()
        qq[:, 2] = lp_radii(qq[:, :2])
        qq[:, 0] = np.clip(qq[:, 0], qq[:, 2], 1 - qq[:, 2])
        qq[:, 1] = np.clip(qq[:, 1], qq[:, 2], 1 - qq[:, 2])

        # float64-safe global shrink via bisection in longdouble
        def feasible(scale):
            ql = qq.astype(np.longdouble).copy()
            ql[:, 2] *= scale
            xx, yy, rr = ql[:, 0], ql[:, 1], ql[:, 2]
            if np.any(xx - rr < 0) or np.any(xx + rr > 1):
                return False
            if np.any(yy - rr < 0) or np.any(yy + rr > 1):
                return False
            for i in range(n):
                ddx = xx[i] - xx[i + 1:]
                ddy = yy[i] - yy[i + 1:]
                dd = np.sqrt(ddx * ddx + ddy * ddy)
                if np.any(dd < rr[i] + rr[i + 1:]):
                    return False
            return True

        lo, hi = 0.0, 1.0
        if feasible(1.0):
            scale = 1.0
        else:
            for _ in range(80):
                mid = 0.5 * (lo + hi)
                if feasible(mid):
                    lo = mid
                else:
                    hi = mid
            scale = lo
        qq[:, 2] *= scale
        return qq

    # ---- Phase 1: SLSQP on full problem ----
    try:
        z = full_slsqp(best.reshape(-1).copy(), deadline - 0.3)
        if z is not None:
            q = clean(unpack(z))
            sc = q[:, 2].sum()
            if sc > best_score and margin(q) >= -1e-9:
                best = q
                best_score = sc
    except Exception:
        pass

    # ---- Phase 2: exact active-set Newton polish ----
    try:
        if time.process_time() < deadline - 0.05:
            qp = exact_polish(best, deadline)
            if qp is not None:
                ok = (np.all(qp[:, 2] > 0) and margin(qp) >= 0)
                if ok:
                    sc = qp[:, 2].sum()
                    if sc > best_score:
                        best = qp
                        best_score = sc
    except Exception:
        pass

    q = best.copy()
    q[:, 2] = np.maximum(q[:, 2] - 1e-15, 1e-12)
    q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
    q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
    for _ in range(500):
        if margin(q) >= 0.0:
            break
        q[:, 2] *= (1.0 - 1e-15)
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
    return q

import numpy as np
import time
from scipy.optimize import minimize, linprog, root


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6
    n = 32
    idx_i, idx_j = np.triu_indices(n, k=1)
    n_pairs = len(idx_i)

    def margin(p):
        x, y, r = p[:, 0], p[:, 1], p[:, 2]
        m = min((x - r).min(), (1 - x - r).min(),
                (y - r).min(), (1 - y - r).min())
        dx = x[:, None] - x[None, :]
        dy = y[:, None] - y[None, :]
        d = np.sqrt(dx * dx + dy * dy) - r[:, None] - r[None, :]
        np.fill_diagonal(d, 1e9)
        return min(m, d.min())

    if start is not None:
        p = np.asarray(start, dtype=float).copy()
        if p.shape != (n, 3):
            p = None
    else:
        p = None
    if p is None:
        k = int(np.ceil(np.sqrt(n)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        p = np.array([[x, y, 0.02] for x, y in pts])

    p[:, 2] = np.maximum(p[:, 2] - 1e-7, 1e-6)
    p[:, 0] = np.clip(p[:, 0], p[:, 2], 1 - p[:, 2])
    p[:, 1] = np.clip(p[:, 1], p[:, 2], 1 - p[:, 2])

    def unpack(z):
        return z.reshape(n, 3)

    def objective(z):
        return -np.sum(z[2::3])

    def obj_grad(z):
        g = np.zeros_like(z)
        g[2::3] = -1.0
        return g

    bounds = []
    for _ in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 0.5))

    def wall_con(z):
        q = unpack(z)
        x, y, r = q[:, 0], q[:, 1], q[:, 2]
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * n, 3 * n))
        for i in range(n):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[n + i, 3 * i] = -1.0; J[n + i, 3 * i + 2] = -1.0
            J[2 * n + i, 3 * i + 1] = 1.0; J[2 * n + i, 3 * i + 2] = -1.0
            J[3 * n + i, 3 * i + 1] = -1.0; J[3 * n + i, 3 * i + 2] = -1.0
        return J

    def pair_con(z):
        q = unpack(z)
        xi, yi, ri = q[idx_i, 0], q[idx_i, 1], q[idx_i, 2]
        xj, yj, rj = q[idx_j, 0], q[idx_j, 1], q[idx_j, 2]
        dx = xi - xj; dy = yi - yj
        return dx * dx + dy * dy - (ri + rj) ** 2

    def pair_jac(z):
        q = unpack(z)
        xi, yi, ri = q[idx_i, 0], q[idx_i, 1], q[idx_i, 2]
        xj, yj, rj = q[idx_j, 0], q[idx_j, 1], q[idx_j, 2]
        dx = xi - xj; dy = yi - yj
        J = np.zeros((n_pairs, 3 * n))
        rows = np.arange(n_pairs)
        J[rows, 3 * idx_i] = 2 * dx
        J[rows, 3 * idx_i + 1] = 2 * dy
        J[rows, 3 * idx_i + 2] = -2 * (ri + rj)
        J[rows, 3 * idx_j] = -2 * dx
        J[rows, 3 * idx_j + 1] = -2 * dy
        J[rows, 3 * idx_j + 2] = -2 * (ri + rj)
        return J

    cons = [
        {'type': 'ineq', 'fun': wall_con, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair_con, 'jac': pair_jac},
    ]

    best = p.copy()
    best_score = p[:, 2].sum() if margin(p) >= -1e-9 else -1e9

    def lp_radii(centers):
        x = centers[:, 0]; y = centers[:, 1]
        wall_cap = np.minimum(np.minimum(x, 1 - x), np.minimum(y, 1 - y))
        wall_cap = np.maximum(wall_cap, 0.0)
        c = -np.ones(n)
        dx = x[idx_i] - x[idx_j]
        dy = y[idx_i] - y[idx_j]
        d = np.hypot(dx, dy)
        A_pair = np.zeros((n_pairs, n))
        A_pair[np.arange(n_pairs), idx_i] = 1.0
        A_pair[np.arange(n_pairs), idx_j] = 1.0
        bounds_lp = [(0.0, wall_cap[i]) for i in range(n)]
        try:
            res = linprog(c, A_ub=A_pair, b_ub=d, bounds=bounds_lp,
                          method='highs')
            if res.success:
                return np.maximum(res.x, 0.0)
        except Exception:
            pass
        rr = wall_cap.copy()
        for i in range(n):
            for j in range(i + 1, n):
                dij = np.hypot(x[i] - x[j], y[i] - y[j])
                if rr[i] + rr[j] > dij:
                    s = (rr[i] + rr[j] - dij) / 2.0
                    rr[i] = max(rr[i] - s, 0.0)
                    rr[j] = max(rr[j] - s, 0.0)
        return rr

    def full_slsqp(z0, deadline_local):
        class TimeUp(Exception):
            pass

        def cb(_z):
            if time.process_time() > deadline_local:
                raise TimeUp()

        try:
            res = minimize(objective, z0, jac=obj_grad, method='SLSQP',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': 1000, 'ftol': 1e-14},
                           callback=cb)
            return res.x
        except TimeUp:
            return None
        except Exception:
            return None

    def clean(q):
        q = q.copy()
        q[:, 2] = np.maximum(q[:, 2], 1e-12)
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
        for i in range(n):
            for j in range(i + 1, n):
                dx = q[i, 0] - q[j, 0]; dy = q[i, 1] - q[j, 1]
                d = np.hypot(dx, dy)
                s = q[i, 2] + q[j, 2]
                if d < s and s > 0:
                    shrink = (s - d) / 2.0 + 1e-12
                    q[i, 2] = max(q[i, 2] - shrink, 1e-12)
                    q[j, 2] = max(q[j, 2] - shrink, 1e-12)
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
        return q

    rng = np.random.default_rng(2024)

    def try_from_centers(centers, tlimit):
        q0 = np.zeros((n, 3))
        q0[:, :2] = centers
        rr = lp_radii(centers)
        q0[:, 2] = np.maximum(rr - 1e-10, 1e-9)
        q0[:, 0] = np.clip(q0[:, 0], q0[:, 2], 1 - q0[:, 2])
        q0[:, 1] = np.clip(q0[:, 1], q0[:, 2], 1 - q0[:, 2])
        z = full_slsqp(q0.reshape(-1).copy(), tlimit)
        if z is None:
            return None
        q = clean(unpack(z))
        if margin(q) >= -1e-9:
            return q
        return None

    if time.process_time() < deadline - 0.2:
        q = try_from_centers(best[:, :2].copy(), deadline - 0.15)
        if q is not None and q[:, 2].sum() > best_score:
            best = q
            best_score = q[:, 2].sum()

    base_centers = best[:, :2].copy()
    attempt = 0
    while time.process_time() < deadline - 0.25:
        attempt += 1
        centers = base_centers.copy()
        mode = attempt % 4
        if mode == 0:
            scale = 0.04 * rng.random()
            centers += rng.normal(0, scale, centers.shape)
        elif mode == 1:
            k = rng.integers(3, 10)
            idxs = rng.choice(n, size=k, replace=False)
            scale = 0.06
            centers[idxs] += rng.normal(0, scale, (k, 2))
        elif mode == 2:
            i, j = rng.choice(n, size=2, replace=False)
            centers[[i, j]] = centers[[j, i]]
        else:
            ax, ay = rng.random(), rng.random()
            centers = 0.5 * centers + 0.5 * np.array([ax, ay])
            centers += rng.normal(0, 0.02, centers.shape)
        centers = np.clip(centers, 0.0, 1.0)
        tlimit = min(deadline - 0.2, time.process_time() + 0.5)
        q = try_from_centers(centers, tlimit)
        if q is not None:
            sc = q[:, 2].sum()
            if sc > best_score - 1e-6:
                base_centers = q[:, :2].copy()
                if sc > best_score:
                    best = q
                    best_score = sc

    def feasible_scale(qq):
        def feasible(scale):
            ql = qq.astype(np.longdouble).copy()
            ql[:, 2] *= scale
            xx, yy, rr = ql[:, 0], ql[:, 1], ql[:, 2]
            if np.any(xx - rr < 0) or np.any(xx + rr > 1):
                return False
            if np.any(yy - rr < 0) or np.any(yy + rr > 1):
                return False
            for i in range(n):
                ddx = xx[i] - xx[i + 1:]
                ddy = yy[i] - yy[i + 1:]
                dd = np.sqrt(ddx * ddx + ddy * ddy)
                if np.any(dd < rr[i] + rr[i + 1:]):
                    return False
            return True

        lo, hi = 0.0, 1.0
        if feasible(1.0):
            scale = 1.0
        else:
            for _ in range(80):
                mid = 0.5 * (lo + hi)
                if feasible(mid):
                    lo = mid
                else:
                    hi = mid
            scale = lo
        return scale

    def exact_polish(qin, deadline_local, extra_pairs=None):
        q = qin.copy()
        x, y, r = q[:, 0], q[:, 1], q[:, 2]
        dx = x[idx_i] - x[idx_j]
        dy = y[idx_i] - y[idx_j]
        d = np.hypot(dx, dy)
        pair_gaps = d - (r[idx_i] + r[idx_j])
        tol = 1e-6
        ap = list(np.where(pair_gaps < tol)[0])
        if extra_pairs is not None:
            for ep in extra_pairs:
                if ep not in ap:
                    ap.append(int(ep))
        ap = np.array(ap, dtype=int)
        wg = np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])
        aw = np.where(wg < tol)[0]
        m = len(ap) + len(aw)
        if m == 0:
            return q

        def cons_all(z):
            parts = []
            if len(ap):
                parts.append(pair_con(z)[ap])
            if len(aw):
                parts.append(wall_con(z)[aw])
            return np.concatenate(parts)

        def cons_jac_all(z):
            rows = []
            if len(ap):
                rows.append(pair_jac(z)[ap])
            if len(aw):
                rows.append(wall_jac(z)[aw])
            return np.vstack(rows)

        z = q.reshape(-1).copy()
        J = cons_jac_all(z)
        g = obj_grad(z)
        try:
            lam, *_ = np.linalg.lstsq(J.T, -g, rcond=None)
        except Exception:
            lam = np.zeros(m)

        def F(u):
            zz = u[:3 * n]
            ll = u[3 * n:]
            c = cons_all(zz)
            Jz = cons_jac_all(zz)
            grad = obj_grad(zz) + Jz.T @ ll
            return np.concatenate([c, grad])

        u0 = np.concatenate([z, lam])
        try:
            sol = root(F, u0, method='hybr',
                       options={'xtol': 1e-14, 'maxfev': 2000})
            if not np.all(np.isfinite(sol.x)):
                return q
            zz = sol.x[:3 * n]
            qq = unpack(zz).copy()
        except Exception:
            return q
        qq[:, 2] = lp_radii(qq[:, :2])
        qq[:, 0] = np.clip(qq[:, 0], qq[:, 2], 1 - qq[:, 2])
        qq[:, 1] = np.clip(qq[:, 1], qq[:, 2], 1 - qq[:, 2])
        scale = feasible_scale(qq)
        qq[:, 2] *= scale
        for _ in range(200):
            if margin(qq) >= 0.0:
                break
            qq[:, 2] *= (1.0 - 1e-15)
        return qq

    if time.process_time() < deadline - 0.05:
        try:
            qp = exact_polish(best, deadline)
            if qp is not None and margin(qp) >= 0.0 and np.all(qp[:, 2] > 0):
                sc = qp[:, 2].sum()
                if sc > best_score:
                    best = qp
                    best_score = sc
        except Exception:
            pass

    # ---- Contact-graph surgery: force a loose pair to touch and re-solve ----
    try:
        x, y, r = best[:, 0], best[:, 1], best[:, 2]
        dx = x[idx_i] - x[idx_j]
        dy = y[idx_i] - y[idx_j]
        d = np.hypot(dx, dy)
        gaps = d - (r[idx_i] + r[idx_j])
        order = np.argsort(-gaps)
        candidates = order[:5]
        for k, ci in enumerate(candidates):
            if time.process_time() > deadline - 0.05:
                break
            try:
                qp = exact_polish(best, deadline, extra_pairs=[int(ci)])
                if qp is not None and margin(qp) >= 0.0 and np.all(qp[:, 2] > 0):
                    sc = qp[:, 2].sum()
                    if sc > best_score + 1e-12:
                        best = qp
                        best_score = sc
            except Exception:
                continue
    except Exception:
        pass

    q = best.copy()
    q[:, 2] = np.maximum(q[:, 2] - 1e-15, 1e-12)
    q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
    q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
    for _ in range(500):
        if margin(q) >= 0.0:
            break
        q[:, 2] *= (1.0 - 1e-15)
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
    return q

