        q = qin.copy()
        x, y, r = q[:, 0], q[:, 1], q[:, 2]
        dx = x[idx_i] - x[idx_j]
        dy = y[idx_i] - y[idx_j]
        d = np.hypot(dx, dy)
        pair_gaps = d - (r[idx_i] + r[idx_j])
        tol = 1e-6
        ap = np.where(pair_gaps < tol)[0]
        wg = np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])
        aw = np.where(wg < tol)[0]
        m = len(ap) + len(aw)
        if m == 0:
            return q

        def cons_all(z):
            parts = []
            if len(ap):
                parts.append(pair_con(z)[ap])
            if len(aw):
                parts.append(wall_con(z)[aw])
            return np.concatenate(parts)

        def cons_jac_all(z):
            rows = []
            if len(ap):
                rows.append(pair_jac(z)[ap])
            if len(aw):
                rows.append(wall_jac(z)[aw])
            return np.vstack(rows)

        z = q.reshape(-1).copy()
        J = cons_jac_all(z)
        g = obj_grad(z)
        try:
            lam, *_ = np.linalg.lstsq(J.T, -g, rcond=None)
        except Exception:
            lam = np.zeros(m)

        def F(u):
            zz = u[:3 * n]
            ll = u[3 * n:]
            c = cons_all(zz)
            Jz = cons_jac_all(zz)
            grad = obj_grad(zz) + Jz.T @ ll
            return np.concatenate([c, grad])

        u0 = np.concatenate([z, lam])
        try:
            sol = root(F, u0, method='hybr',
                       options={'xtol': 1e-14, 'maxfev': 2000})
            if not np.all(np.isfinite(sol.x)):
                return q
            zz = sol.x[:3 * n]
            qq = unpack(zz).copy()
        except Exception:
            return q
        qq[:, 2] = lp_radii(qq[:, :2])
        qq[:, 0] = np.clip(qq[:, 0], qq[:, 2], 1 - qq[:, 2])
        qq[:, 1] = np.clip(qq[:, 1], qq[:, 2], 1 - qq[:, 2])

        def feasible(scale):
            ql = qq.astype(np.longdouble).copy()
            ql[:, 2] *= scale
            xx, yy, rr = ql[:, 0], ql[:, 1], ql[:, 2]
            if np.any(xx - rr < 0) or np.any(xx + rr > 1):
                return False
            if np.any(yy - rr < 0) or np.any(yy + rr > 1):
                return False
            for i in range(n):
                ddx = xx[i] - xx[i + 1:]
                ddy = yy[i] - yy[i + 1:]
                dd = np.sqrt(ddx * ddx + ddy * ddy)
                if np.any(dd < rr[i] + rr[i + 1:]):
                    return False
            return True

        lo, hi = 0.0, 1.0
        if feasible(1.0):
            scale = 1.0
        else:
            for _ in range(80):
                mid = 0.5 * (lo + hi)
                if feasible(mid):
                    lo = mid
                else:
                    hi = mid
            scale = lo
        qq[:, 2] *= scale
        for _ in range(200):
            if margin(qq) >= 0.0:
                break
            qq[:, 2] *= (1.0 - 1e-15)
        return qq

    # ---- Structured seed generators ----
    def seed_hex():
        # hexagonal lattice: find spacing h so that ~32 points fit in unit square
        # rows spaced h*(sqrt(3)/2), alternate rows offset h/2
        best_pts = None
        for nrows in range(4, 9):
            dy = 1.0 / max(nrows - 1, 1)
            h = dy / (np.sqrt(3) / 2.0)
            pts = []
            for k in range(nrows):
                yk = k * h * (np.sqrt(3) / 2.0)
                if yk > 1.0 + 1e-9:
                    break
                offset = (h / 2.0) if (k % 2) else 0.0
                ncols = int(np.floor((1.0 - offset) / h)) + 1
                for c in range(max(ncols, 0)):
                    xk = offset + c * h
                    if 0.0 <= xk <= 1.0:
                        pts.append((xk, yk))
            if len(pts) >= n:
                pts = pts[:n]
                best_pts = pts
                break
            if best_pts is None or len(pts) > len(best_pts):
                best_pts = pts
        if best_pts is None or len(best_pts) < n:
            # fallback: fill remaining with grid
            k = int(np.ceil(np.sqrt(n)))
            grid = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)]
            pts = list(best_pts) if best_pts else []
            for g in grid:
                if len(pts) >= n:
                    break
                pts.append(g)
            best_pts = pts[:n]
        return np.array(best_pts[:n], dtype=float)

    def seed_corner():
        pts = [(0.15, 0.15), (0.85, 0.15), (0.15, 0.85), (0.85, 0.85)]
        # 5x6 interior grid (30 points) -> take 28
        nx, ny = 6, 5
        for j in range(ny):
            for i in range(nx):
                x = (i + 0.5) / nx
                y = (j + 0.5) / ny
                pts.append((x, y))
        return np.array(pts[:n], dtype=float)

    def seed_boundary_ring():
        pts = [(0.1, 0.1), (0.9, 0.1), (0.1, 0.9), (0.9, 0.9)]
        # evenly spaced on edges
        per_edge = 4  # 4 per edge * 4 edges = 16, but corners already there
        for i in range(1, per_edge + 1):
            t = i / (per_edge + 1)
            pts.append((t, 0.05))       # bottom
            pts.append((t, 0.95))       # top
            pts.append((0.05, t))       # left
            pts.append((0.95, t))       # right
        # interior grid to fill up to 32
        k = int(np.ceil(np.sqrt(n)))
        for j in range(k):
            for i in range(k):
                if len(pts) >= n:
                    break
                x = (i + 0.5) / k
                y = (j + 0.5) / k
                pts.append((x, y))
            if len(pts) >= n:
                break
        return np.array(pts[:n], dtype=float)

    # Baseline: polish start directly
    if time.process_time() < deadline - 0.2:
        q = try_from_centers(best[:, :2].copy(), deadline - 0.15)
        if q is not None and q[:, 2].sum() > best_score:
            best = q
            best_score = q[:, 2].sum()

    # ---- Run the three structured seeds ----
    structured_seeds = [("hex", seed_hex()),
                        ("corner", seed_corner()),
                        ("ring", seed_boundary_ring())]
    for name, centers in structured_seeds:
        if time.process_time() > deadline - 0.3:
            break
        centers = np.clip(centers, 0.0, 1.0)
        tlimit = min(deadline - 0.25, time.process_time() + 1.0)
        q = try_from_centers(centers, tlimit)
        if q is not None:
            sc = q[:, 2].sum()
            if sc > best_score:
                best = q
                best_score = sc
            # also try exact_polish on this seed's result
            if time.process_time() < deadline - 0.2:
                try:
                    qp = exact_polish(q, deadline)
                    if qp is not None and margin(qp) >= 0.0 and np.all(qp[:, 2] > 0):
                        sc2 = qp[:, 2].sum()
                        if sc2 > best_score:
                            best = qp
                            best_score = sc2
                except Exception:
                    pass

    # ---- Basin-hopping / random-restart descent on centers+LP radii ----
    base_centers = best[:, :2].copy()
    attempt = 0
    while time.process_time() < deadline - 0.25:
        attempt += 1
        centers = base_centers.copy()
        mode = attempt % 4
        if mode == 0:
            scale = 0.04 * rng.random()
            centers += rng.normal(0, scale, centers.shape)
        elif mode == 1:
            k = rng.integers(3, 10)
            idxs = rng.choice(n, size=k, replace=False)
            scale = 0.06
            centers[idxs] += rng.normal(0, scale, (k, 2))
        elif mode == 2:
            i, j = rng.choice(n, size=2, replace=False)
            centers[[i, j]] = centers[[j, i]]
        else:
            ax, ay = rng.random(), rng.random()
            centers = 0.5 * centers + 0.5 * np.array([ax, ay])
            centers += rng.normal(0, 0.02, centers.shape)
        centers = np.clip(centers, 0.0, 1.0)
        tlimit = min(deadline - 0.2, time.process_time() + 0.5)
        q = try_from_centers(centers, tlimit)
        if q is not None:
            sc = q[:, 2].sum()
            if sc > best_score - 1e-6:
                base_centers = q[:, :2].copy()
                if sc > best_score:
                    best = q
                    best_score = sc

    # ---- Final exact polish ----
    if time.process_time() < deadline - 0.05:
        try:
            qp = exact_polish(best, deadline)
            if qp is not None and margin(qp) >= 0.0 and np.all(qp[:, 2] > 0):
                sc = qp[:, 2].sum()
                if sc > best_score:
                    best = qp
                    best_score = sc
        except Exception:
            pass

    q = best.copy()
    q[:, 2] = np.maximum(q[:, 2] - 1e-15, 1e-12)
    q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
    q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
    for _ in range(500):
        if margin(q) >= 0.0:
            break
        q[:, 2] *= (1.0 - 1e-15)
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
    return q

import numpy as np
import time
from scipy.optimize import minimize, linprog, root


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6
    n = 32
    idx_i, idx_j = np.triu_indices(n, k=1)
    n_pairs = len(idx_i)

    def margin(p):
        x, y, r = p[:, 0], p[:, 1], p[:, 2]
        m = min((x - r).min(), (1 - x - r).min(),
                (y - r).min(), (1 - y - r).min())
        dx = x[:, None] - x[None, :]
        dy = y[:, None] - y[None, :]
        d = np.sqrt(dx * dx + dy * dy) - r[:, None] - r[None, :]
        np.fill_diagonal(d, 1e9)
        return min(m, d.min())

    if start is not None:
        p = np.asarray(start, dtype=float).copy()
        if p.shape != (n, 3):
            p = None
    else:
        p = None
    if p is None:
        k = int(np.ceil(np.sqrt(n)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        p = np.array([[x, y, 0.02] for x, y in pts])

    p[:, 2] = np.maximum(p[:, 2] - 1e-7, 1e-6)
    p[:, 0] = np.clip(p[:, 0], p[:, 2], 1 - p[:, 2])
    p[:, 1] = np.clip(p[:, 1], p[:, 2], 1 - p[:, 2])

    def unpack(z):
        return z.reshape(n, 3)

    def objective(z):
        return -np.sum(z[2::3])

    def obj_grad(z):
        g = np.zeros_like(z)
        g[2::3] = -1.0
        return g

    bounds = []
    for _ in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 0.5))

    def wall_con(z):
        q = unpack(z)
        x, y, r = q[:, 0], q[:, 1], q[:, 2]
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * n, 3 * n))
        for i in range(n):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[n + i, 3 * i] = -1.0; J[n + i, 3 * i + 2] = -1.0
            J[2 * n + i, 3 * i + 1] = 1.0; J[2 * n + i, 3 * i + 2] = -1.0
            J[3 * n + i, 3 * i + 1] = -1.0; J[3 * n + i, 3 * i + 2] = -1.0
        return J

    def pair_con(z):
        q = unpack(z)
        xi, yi, ri = q[idx_i, 0], q[idx_i, 1], q[idx_i, 2]
        xj, yj, rj = q[idx_j, 0], q[idx_j, 1], q[idx_j, 2]
        dx = xi - xj; dy = yi - yj
        return dx * dx + dy * dy - (ri + rj) ** 2

    def pair_jac(z):
        q = unpack(z)
        xi, yi, ri = q[idx_i, 0], q[idx_i, 1], q[idx_i, 2]
        xj, yj, rj = q[idx_j, 0], q[idx_j, 1], q[idx_j, 2]
        dx = xi - xj; dy = yi - yj
        J = np.zeros((n_pairs, 3 * n))
        rows = np.arange(n_pairs)
        J[rows, 3 * idx_i] = 2 * dx
        J[rows, 3 * idx_i + 1] = 2 * dy
        J[rows, 3 * idx_i + 2] = -2 * (ri + rj)
        J[rows, 3 * idx_j] = -2 * dx
        J[rows, 3 * idx_j + 1] = -2 * dy
        J[rows, 3 * idx_j + 2] = -2 * (ri + rj)
        return J

    cons = [
        {'type': 'ineq', 'fun': wall_con, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair_con, 'jac': pair_jac},
    ]

    best = p.copy()
    best_score = p[:, 2].sum() if margin(p) >= -1e-9 else -1e9

    def lp_radii(centers):
        x = centers[:, 0]; y = centers[:, 1]
        wall_cap = np.minimum(np.minimum(x, 1 - x), np.minimum(y, 1 - y))
        wall_cap = np.maximum(wall_cap, 0.0)
        c = -np.ones(n)
        dx = x[idx_i] - x[idx_j]
        dy = y[idx_i] - y[idx_j]
        d = np.hypot(dx, dy)
        A_pair = np.zeros((n_pairs, n))
        A_pair[np.arange(n_pairs), idx_i] = 1.0
        A_pair[np.arange(n_pairs), idx_j] = 1.0
        bounds_lp = [(0.0, wall_cap[i]) for i in range(n)]
        try:
            res = linprog(c, A_ub=A_pair, b_ub=d, bounds=bounds_lp,
                          method='highs')
            if res.success:
                return np.maximum(res.x, 0.0)
        except Exception:
            pass
        rr = wall_cap.copy()
        for i in range(n):
            for j in range(i + 1, n):
                dij = np.hypot(x[i] - x[j], y[i] - y[j])
                if rr[i] + rr[j] > dij:
                    s = (rr[i] + rr[j] - dij) / 2.0
                    rr[i] = max(rr[i] - s, 0.0)
                    rr[j] = max(rr[j] - s, 0.0)
        return rr

    def full_slsqp(z0, deadline_local):
        class TimeUp(Exception):
            pass

        def cb(_z):
            if time.process_time() > deadline_local:
                raise TimeUp()

        try:
            res = minimize(objective, z0, jac=obj_grad, method='SLSQP',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': 1000, 'ftol': 1e-14},
                           callback=cb)
            return res.x
        except TimeUp:
            return None
        except Exception:
            return None

    def clean(q):
        q = q.copy()
        q[:, 2] = np.maximum(q[:, 2], 1e-12)
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
        for i in range(n):
            for j in range(i + 1, n):
                dx = q[i, 0] - q[j, 0]; dy = q[i, 1] - q[j, 1]
                d = np.hypot(dx, dy)
                s = q[i, 2] + q[j, 2]
                if d < s and s > 0:
                    shrink = (s - d) / 2.0 + 1e-12
                    q[i, 2] = max(q[i, 2] - shrink, 1e-12)
                    q[j, 2] = max(q[j, 2] - shrink, 1e-12)
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
        return q

    rng = np.random.default_rng(2024)

    def try_from_centers(centers, tlimit):
        q0 = np.zeros((n, 3))
        q0[:, :2] = centers
        rr = lp_radii(centers)
        q0[:, 2] = np.maximum(rr - 1e-10, 1e-9)
        q0[:, 0] = np.clip(q0[:, 0], q0[:, 2], 1 - q0[:, 2])
        q0[:, 1] = np.clip(q0[:, 1], q0[:, 2], 1 - q0[:, 2])
        z = full_slsqp(q0.reshape(-1).copy(), tlimit)
        if z is None:
            return None
        q = clean(unpack(z))
        if margin(q) >= -1e-9:
            return q
        return None

    # ---- Structured deterministic seeds ----
    def seed_grid57():
        # 5x7 grid minus 3 corners
        pts = []
        for j in range(5):
            for i in range(7):
                pts.append(((i + 0.5) / 7.0, (j + 0.5) / 5.0))
        # remove 3 corners (indices in the 5x7 grid)
        # corners: (0,0)=0, (6,0)=6, (0,4)=28, (6,4)=34
        remove = {0, 6, 28}
        pts = [p for k, p in enumerate(pts) if k not in remove]
        return np.array(pts[:n])

    def seed_hex():
        # hexagonal rows of 6-5-6-5-6-4 = 32
        rows = [6, 5, 6, 5, 6, 4]
        nrows = len(rows)
        pts = []
        dy = 1.0 / nrows
        for j, cnt in enumerate(rows):
            y = (j + 0.5) * dy
            offset = 0.5 / cnt if (j % 2 == 0) else 0.5 / cnt
            # stagger: alternate rows shifted by half spacing
            for i in range(cnt):
                if j % 2 == 0:
                    x = (i + 0.5) / cnt
                else:
                    x = (i + 0.5) / cnt
                pts.append((x, y))
        return np.array(pts[:n])

    def seed_hex_jitter(scale):
        base = seed_hex()
        return np.clip(base + rng.normal(0, scale, base.shape), 0.0, 1.0)

    # Baseline: polish start directly
    if time.process_time() < deadline - 0.2:
        q = try_from_centers(best[:, :2].copy(), deadline - 0.15)
        if q is not None and q[:, 2].sum() > best_score:
            best = q
            best_score = q[:, 2].sum()

    # Try structured seeds
    seeds = [seed_grid57(), seed_hex()]
    for sc in (0.01, 0.02, 0.03):
        seeds.append(seed_hex_jitter(sc))

    for centers in seeds:
        if time.process_time() > deadline - 0.3:
            break
        tlimit = min(deadline - 0.25, time.process_time() + 0.6)
        q = try_from_centers(centers, tlimit)
        if q is not None:
            sc = q[:, 2].sum()
            if sc > best_score:
                best = q
                best_score = sc

    # Then continue with perturbations from best
    base_centers = best[:, :2].copy()
    attempt = 0
    while time.process_time() < deadline - 0.25:
        attempt += 1
        centers = base_centers.copy()
        mode = attempt % 4
        if mode == 0:
            scale = 0.04 * rng.random()
            centers += rng.normal(0, scale, centers.shape)
        elif mode == 1:
            k = rng.integers(3, 10)
            idxs = rng.choice(n, size=k, replace=False)
            scale = 0.06
            centers[idxs] += rng.normal(0, scale, (k, 2))
        elif mode == 2:
            i, j = rng.choice(n, size=2, replace=False)
            centers[[i, j]] = centers[[j, i]]
        else:
            ax, ay = rng.random(), rng.random()
            centers = 0.5 * centers + 0.5 * np.array([ax, ay])
            centers += rng.normal(0, 0.02, centers.shape)
        centers = np.clip(centers, 0.0, 1.0)
        tlimit = min(deadline - 0.2, time.process_time() + 0.5)
        q = try_from_centers(centers, tlimit)
        if q is not None:
            sc = q[:, 2].sum()
            if sc > best_score - 1e-6:
                base_centers = q[:, :2].copy()
                if sc > best_score:
                    best = q
                    best_score = sc

    def exact_polish(qin, deadline_local):
        q = qin.copy()
        x, y, r = q[:, 0], q[:, 1], q[:, 2]
        dx = x[idx_i] - x[idx_j]
        dy = y[idx_i] - y[idx_j]
        d = np.hypot(dx, dy)
        pair_gaps = d - (r[idx_i] + r[idx_j])
        tol = 1e-6
        ap = np.where(pair_gaps < tol)[0]
        wg = np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])
        aw = np.where(wg < tol)[0]
        m = len(ap) + len(aw)
        if m == 0:
            return q

        def cons_all(z):
            parts = []
            if len(ap):
                parts.append(pair_con(z)[ap])
            if len(aw):
                parts.append(wall_con(z)[aw])
            return np.concatenate(parts)

        def cons_jac_all(z):
            rows = []
            if len(ap):
                rows.append(pair_jac(z)[ap])
            if len(aw):
                rows.append(wall_jac(z)[aw])
            return np.vstack(rows)

        z = q.reshape(-1).copy()
        J = cons_jac_all(z)
        g = obj_grad(z)
        try:
            lam, *_ = np.linalg.lstsq(J.T, -g, rcond=None)
        except Exception:
            lam = np.zeros(m)

        def F(u):
            zz = u[:3 * n]
            ll = u[3 * n:]
            c = cons_all(zz)
            Jz = cons_jac_all(zz)
            grad = obj_grad(zz) + Jz.T @ ll
            return np.concatenate([c, grad])

        u0 = np.concatenate([z, lam])
        try:
            sol = root(F, u0, method='hybr',
                       options={'xtol': 1e-14, 'maxfev': 2000})
            if not np.all(np.isfinite(sol.x)):
                return q
            zz = sol.x[:3 * n]
            qq = unpack(zz).copy()
        except Exception:
            return q
        qq[:, 2] = lp_radii(qq[:, :2])
        qq[:, 0] = np.clip(qq[:, 0], qq[:, 2], 1 - qq[:, 2])
        qq[:, 1] = np.clip(qq[:, 1], qq[:, 2], 1 - qq[:, 2])

        def feasible(scale):
            ql = qq.astype(np.longdouble).copy()
            ql[:, 2] *= scale
            xx, yy, rr = ql[:, 0], ql[:, 1], ql[:, 2]
            if np.any(xx - rr < 0) or np.any(xx + rr > 1):
                return False
            if np.any(yy - rr < 0) or np.any(yy + rr > 1):
                return False
            for i in range(n):
                ddx = xx[i] - xx[i + 1:]
                ddy = yy[i] - yy[i + 1:]
                dd = np.sqrt(ddx * ddx + ddy * ddy)
                if np.any(dd < rr[i] + rr[i + 1:]):
                    return False
            return True

        lo, hi = 0.0, 1.0
        if feasible(1.0):
            scale = 1.0
        else:
            for _ in range(80):
                mid = 0.5 * (lo + hi)
                if feasible(mid):
                    lo = mid
                else:
                    hi = mid
            scale = lo
        qq[:, 2] *= scale
        for _ in range(200):
            if margin(qq) >= 0.0:
                break
            qq[:, 2] *= (1.0 - 1e-15)
        return qq

    if time.process_time() < deadline - 0.05:
        try:
            qp = exact_polish(best, deadline)
            if qp is not None and margin(qp) >= 0.0 and np.all(qp[:, 2] > 0):
                sc = qp[:, 2].sum()
                if sc > best_score:
                    best = qp
                    best_score = sc
        except Exception:
            pass

    q = best.copy()
    q[:, 2] = np.maximum(q[:, 2] - 1e-15, 1e-12)
    q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
    q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
    for _ in range(500):
        if margin(q) >= 0.0:
            break
        q[:, 2] *= (1.0 - 1e-15)
        q[:, 0] = np.clip(q[:, 0], q[:, 2], 1 - q[:, 2])
        q[:, 1] = np.clip(q[:, 1], q[:, 2], 1 - q[:, 2])
    return q
